#!/usr/bin/env bash
# Question 8: Node drain is stuck. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q8_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q8_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q8_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl label node "${Q8_NODE}" maintenance=due --overwrite
for n in "worker-1" "worker-2"; do
  [[ "$n" == "${Q8_NODE}" ]] || kubectl label node "$n" maintenance- >/dev/null 2>&1 || true
done
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q8_APP}
  namespace: ${Q8_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q8_APP} }
  template:
    metadata:
      labels: { app: ${Q8_APP} }
    spec:
      affinity:
        nodeAffinity:
          preferredDuringSchedulingIgnoredDuringExecution:
            - weight: 100
              preference:
                matchExpressions: [{ key: maintenance, operator: In, values: [due] }]
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          resources:
            requests: { cpu: 50m, memory: 32Mi }
---
apiVersion: policy/v1
kind: PodDisruptionBudget
metadata:
  name: ${Q8_APP}-pdb
  namespace: ${Q8_NS}
spec:
  minAvailable: 1
  selector:
    matchLabels: { app: ${Q8_APP} }
EOF

case "${Q8_FAULT}" in
  pdb-min-available)
    kubectl -n "${Q8_NS}" patch pdb "${Q8_APP}-pdb" --type=merge -p '{"spec":{"minAvailable":2}}'
    ;;
  pdb-max-unavailable-0)
    kubectl -n "${Q8_NS}" patch pdb "${Q8_APP}-pdb" --type=merge -p '{"spec":{"minAvailable":null,"maxUnavailable":0}}'
    ;;
  pinned-node-selector)
    kubectl -n "${Q8_NS}" patch deployment "${Q8_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"nodeSelector":{"maintenance":"due"}}}}}'
    ;;
  replica-anti-affinity)
    kubectl -n "${Q8_NS}" patch deployment "${Q8_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"affinity":{"podAntiAffinity":{"requiredDuringSchedulingIgnoredDuringExecution":[{"labelSelector":{"matchLabels":{"app":"'"${Q8_APP}"'"}},"topologyKey":"kubernetes.io/hostname"}]}}}}}}'
    ;;
  bare-pod)
    kubectl -n "${Q8_NS}" run "${Q8_APP}-debug" --image=busybox:1.36 --restart=Never --overrides='{"spec":{"nodeName":"'"${Q8_NODE}"'"}}' --command -- sleep infinity >/dev/null
    kubectl -n "${Q8_NS}" wait --for=condition=Ready "pod/${Q8_APP}-debug" --timeout=120s >/dev/null
    ;;
  emptydir-pod)
    kubectl -n "${Q8_NS}" patch deployment "${Q8_APP}" --type=strategic -p '{"spec":{"template":{"spec":{"volumes":[{"name":"scratch","emptyDir":{}}],"containers":[{"name":"web","volumeMounts":[{"name":"scratch","mountPath":"/var/cache/scratch"}]}]}}}}'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q8_NS}" scale "deployment/${Q8_APP}" --replicas=2
kubectl -n "${Q8_NS}" rollout status "deployment/${Q8_APP}" --timeout=240s
[[ -n "$(kubectl -n "${Q8_NS}" get pods --field-selector "spec.nodeName=${Q8_NODE}" -o name 2>/dev/null)" ]] || { echo "nothing of ${Q8_NS} runs on the maintenance worker" >&2; exit 1; }
# The question only makes sense if the plain drain cannot finish the job: try it, then put everything back.
kubectl drain "${Q8_NODE}" --ignore-daemonsets --timeout=20s >/dev/null 2>&1 || true
drained=no
[[ -z "$(kubectl -n "${Q8_NS}" get pods --field-selector "spec.nodeName=${Q8_NODE}" -o name 2>/dev/null)" && "$(kubectl -n "${Q8_NS}" get deployment "${Q8_APP}" -o jsonpath='{.status.readyReplicas}')" == 2 ]] && drained=yes
kubectl uncordon "${Q8_NODE}" >/dev/null
[[ "$drained" == no ]] || { echo "the worker drains cleanly" >&2; exit 1; }
kubectl -n "${Q8_NS}" rollout status "deployment/${Q8_APP}" --timeout=180s >/dev/null
